def test_pad_forced_codegen_refuses_out_of_scope_case(device, expect_error):
    shape, kwargs, dtype, layout, placement = _REFUSED_CASE
    xt = ttnn.from_torch(_make_input(shape, dtype), dtype=dtype, layout=layout, device=device, memory_config=placement)
    with expect_error(RuntimeError, "does not support"):
        _force_codegen(xt, **kwargs)


